// ------------------------------------------------------------ stats
let STATS = {};
let statsDirty = false;
const STAT_NAMES = { k: "Bajas", d: "Muertes", dw: "Duelos ganados", dl: "Duelos perdidos", hw: "Cazas ganadas", hl: "Cazas perdidas", ck: "Bajas en campal" };

function loadStats() {
  try {
    STATS = JSON.parse(world.getDynamicProperty("natura:stats") ?? "{}");
  } catch {
    STATS = {};
  }
}

function addStat(player, key, n = 1) {
  const name = typeof player === "string" ? player : player.name;
  const s = (STATS[name] ??= {});
  s[key] = (s[key] ?? 0) + n;
  statsDirty = true;
}

function top(key, n = 3) {
  return Object.entries(STATS).filter(([, s]) => s[key] > 0).sort((a, b) => b[1][key] - a[1][key]).slice(0, n);
}

// parkour: the best time (in ticks), lower is better
function topParkour(n = 5) {
  return Object.entries(STATS).filter(([, s]) => s.pk > 0).sort((a, b) => a[1].pk - b[1].pk).slice(0, n);
}

system.runInterval(() => {
  if (!statsDirty) return;
  statsDirty = false;
  let json = JSON.stringify(STATS);
  // keep the property small: forget the players with fewer games
  while (json.length > 30000) {
    const names = Object.keys(STATS).sort((a, b) => sum(STATS[a]) - sum(STATS[b]));
    for (const n of names.slice(0, Math.ceil(names.length / 10))) delete STATS[n];
    json = JSON.stringify(STATS);
  }
  world.setDynamicProperty("natura:stats", json);
}, 100);

function sum(s) {
  return Object.entries(s).reduce((a, [k, v]) => a + (k === "pk" ? 1 : v), 0);
}

// ------------------------------------------------------------ player state
// mode: lobby | duel | hunt | hunt_spec | campal | free
const P = new Map();

function st(player) {
  let s = P.get(player.id);
  if (!s) {
    s = { mode: "lobby", hurtTick: -9999, attacker: undefined, attackerTick: -9999, pad: null, pk: null };
    P.set(player.id, s);
  }
  return s;
}

const built = (id) => world.getDynamicProperty(`natura:built:${id}`) === CFG.buildVersion;

function menuItem(id, name, lore) {
  const item = new ItemStack(id, 1);
  item.nameTag = name;
  try {
    item.setLore([...lore, MENU_LORE]);
  } catch {}
  try {
    item.lockMode = enumv(mc.ItemLockMode, "slot");
  } catch {}
  try {
    item.keepOnDeath = true;
  } catch {}
  return item;
}

const ITEMS = {
  selector: () => menuItem("minecraft:compass", "§a§lMenú de Natura PvP", ["§7Modos, parkour, música y estadísticas"]),
  admin: () => menuItem("minecraft:clock", "§c§lPanel de administración", ["§7Solo para administradores"]),
  leave: () => menuItem("minecraft:recovery_compass", "§c§lVolver al lobby", ["§7Sal del campal"]),
  checkpoint: () => menuItem("minecraft:recovery_compass", "§a§lVolver al punto de control", ["§7Parkour"]),
};

function itemKind(item) {
  if (!item) return undefined;
  let lore = [];
  try {
    lore = item.getLore();
  } catch {}
  if (!lore.includes(MENU_LORE)) return undefined;
  if (item.typeId === "minecraft:compass") return "selector";
  if (item.typeId === "minecraft:clock") return "admin";
  if (item.typeId === "minecraft:recovery_compass") return lore.includes("§7Parkour") ? "checkpoint" : "leave";
  return undefined;
}

function lobbyItems(player) {
  const inv = player.getComponent("minecraft:inventory")?.container;
  if (!inv) return;
  inv.setItem(0, ITEMS.selector());
  inv.setItem(8, isAdmin(player) ? ITEMS.admin() : undefined);
}

// ------------------------------------------------------------ music
// Every player chooses what plays: one song (looping), their own list in their
// order, or all of them. In Emparejamiento and Campal each player hears their
// own choice; in a hunt everybody hears the music the hunted player chose.
const TRACKS = CFG.tracks; // [{ id, name, ticks }]
const DEFAULT_PREFS = { volume: 80, normal: { mode: "all", one: 0, list: [] }, hunt: { mode: "all", one: 0, list: [] }, final: 0 };
const validTrack = (i) => Number.isInteger(i) && i >= 0 && i < TRACKS.length;
const trackLen = (t) => fmtTime(Math.round((t.ticks - 10) / SEC));

function prefs(player) {
  const out = clone(DEFAULT_PREFS);
  try {
    const saved = JSON.parse(player.getDynamicProperty("natura:music") ?? "null");
    if (saved) {
      if (typeof saved.volume === "number") out.volume = Math.max(0, Math.min(100, saved.volume));
      Object.assign(out.normal, saved.normal ?? {});
      Object.assign(out.hunt, saved.hunt ?? {});
      if (saved.final === -1 || validTrack(saved.final)) out.final = saved.final;
    }
  } catch {}
  return out;
}

function savePrefs(player, p) {
  player.setDynamicProperty("natura:music", JSON.stringify(p));
}

function queueOf(pl) {
  const one = validTrack(pl.one) ? pl.one : 0;
  switch (pl.mode) {
    case "off": return [];
    case "one": return [one];
    case "list": {
      const list = (pl.list ?? []).filter(validTrack);
      return list.length ? list : [one];
    }
    case "shuffle": return shuffle(TRACKS.map((_, i) => i));
    default: return TRACKS.map((_, i) => i);
  }
}

function describePlaylist(pl) {
  if (pl.mode === "off") return "sin música";
  if (pl.mode === "one") return `${TRACKS[validTrack(pl.one) ? pl.one : 0]?.name} (en bucle)`;
  if (pl.mode === "list") {
    const q = queueOf(pl);
    return q.length === 1 ? `${TRACKS[q[0]].name} (en bucle)` : `mi lista (${q.length} canciones)`;
  }
  return pl.mode === "shuffle" ? "todas, al azar" : "todas, en orden";
}

const playing = new Map(); // player id -> sound id playing now
const pendingPlay = new Map(); // player id -> token of the song about to start
const personal = new Map(); // player id -> { queue, i, end }
let huntMusic = null; // { queue, i, end }

// The song starts a few ticks after the previous one is stopped: a "stopsound"
// and a "playsound" of the same song in the same tick left the player in silence.
function playTrack(player, index, announce = true) {
  stopSong(player);
  const t = TRACKS[index];
  const vol = prefs(player).volume / 100;
  if (!t || vol <= 0) return;
  const token = {};
  pendingPlay.set(player.id, token);
  playing.set(player.id, t.id);
  system.runTimeout(() => {
    if (pendingPlay.get(player.id) !== token || !valid(player)) return;
    pendingPlay.delete(player.id);
    try {
      player.playSound(t.id, { volume: vol });
    } catch {}
    if (announce) bar(player, `§d♪ §f${t.name}`);
  }, 4);
}

function stopSong(player) {
  pendingPlay.delete(player.id);
  const id = playing.get(player.id);
  if (!id) return;
  pcmd(player, `stopsound @s ${id}`);
  playing.delete(player.id);
}

function playPersonal(player, queue) {
  personal.delete(player.id);
  stopSong(player);
  if (!queue.length) return;
  personal.set(player.id, { queue, i: 0, end: system.currentTick + TRACKS[queue[0]].ticks });
  playTrack(player, queue[0]);
}

function stopMusic(player) {
  personal.delete(player.id);
  stopSong(player);
}

// a mode starts: the player's own music for Emparejamiento and Campal
function modeMusic(player) {
  playPersonal(player, queueOf(prefs(player).normal));
}

function huntMusicStart(queue) {
  huntMusic = queue.length ? { queue, i: 0, end: system.currentTick + TRACKS[queue[0]].ticks } : null;
  for (const p of huntParticipants()) {
    personal.delete(p.id);
    if (huntMusic) playTrack(p, queue[0]);
    else stopSong(p);
  }
}

function huntMusicJoin(player) {
  personal.delete(player.id);
  if (huntMusic) playTrack(player, huntMusic.queue[huntMusic.i]);
}

function huntMusicStop() {
  huntMusic = null;
  for (const p of huntParticipants()) stopSong(p);
}

// what this player is hearing now (to play it again)
function currentTrack(player) {
  const m = personal.get(player.id);
  if (m) return m.queue[m.i];
  if (huntMusic && huntParticipants().some((x) => x.id === player.id)) return huntMusic.queue[huntMusic.i];
  return undefined;
}

// the songs loop: when one ends, the next one (or the same one) starts
system.runInterval(() => {
  const now = system.currentTick;
  for (const [id, m] of personal) {
    const p = byId(id);
    if (!p) {
      personal.delete(id);
      playing.delete(id);
      continue;
    }
    if (now < m.end) continue;
    m.i = (m.i + 1) % m.queue.length;
    m.end = now + TRACKS[m.queue[m.i]].ticks;
    playTrack(p, m.queue[m.i], m.queue.length > 1);
  }
  if (huntMusic && now >= huntMusic.end) {
    huntMusic.i = (huntMusic.i + 1) % huntMusic.queue.length;
    huntMusic.end = now + TRACKS[huntMusic.queue[huntMusic.i]].ticks;
    for (const p of huntParticipants()) playTrack(p, huntMusic.queue[huntMusic.i], huntMusic.queue.length > 1);
  }
}, 5);

system.runInterval(() => cmd("weather clear"), 60 * SEC);

// ------------------------------------------------------------ lobby
function sendToLobby(player, message) {
  const s = st(player);
  s.mode = "lobby";
  s.role = undefined;
  s.pad = "spawn";
  s.pk = null;
  stopMusic(player);
  camClear(player);
  hud(player, true);
  setMode(player, GM.adventure);
  clearPlayer(player);
  heal(player);
  effect(player, "resistance", 10, 255);
  tp(player, LOBBY.spawn, LOBBY.look);
  try {
    player.setSpawnPoint({ dimension: overworld(), x: Math.floor(LOBBY.spawn.x), y: LOBBY.spawn.y, z: Math.floor(LOBBY.spawn.z) });
  } catch {}
  lobbyItems(player);
  if (message) player.sendMessage(message);
}

function leaveQueues(player) {
  const a = duel.queue.indexOf(player.id);
  if (a >= 0) duel.queue.splice(a, 1);
  const b = hunt.queue.indexOf(player.id);
  if (b >= 0) hunt.queue.splice(b, 1);
}

function inCombat(player) {
  const s = st(player);
  return system.currentTick - s.hurtTick < S.campal.combatTag * SEC;
}

function lockEffects(p, seconds) {
  effect(p, "slowness", seconds, 255);
  effect(p, "weakness", seconds, 255);
  effect(p, "resistance", seconds, 255);
}

function unlock(p) {
  for (const e of ["slowness", "weakness", "resistance", "blindness"]) {
    try {
      p.removeEffect(e);
    } catch {}
  }
}

// ------------------------------------------------------------ parkour
const PK = PARKOUR;

function startParkour(player) {
  const s = st(player);
  s.pk = { cp: 0, start: system.currentTick, falls: 0 };
  player.getComponent("minecraft:inventory")?.container?.setItem(4, ITEMS.checkpoint());
  title(player, "§a§lPARKOUR", "§fsube por la raíz y salta alrededor del Árbol del Mundo", 50);
  player.sendMessage(`§2[Parkour]§r ¡Empieza el tiempo! Sube por la raíz hasta el tronco y salta hasta la cima. ${PK.checkpoints.length - 1} puntos de control. Si caes, vuelves al último.`);
  sound(player, "random.orb", 1, 1.2);
}

function stopParkour(player, message) {
  const s = st(player);
  if (!s.pk) return;
  s.pk = null;
  const inv = player.getComponent("minecraft:inventory")?.container;
  if (itemKind(inv?.getItem(4)) === "checkpoint") inv.setItem(4, undefined);
  if (message) player.sendMessage(message);
}

function toCheckpoint(player) {
  const s = st(player);
  if (!s.pk) return;
  const cp = PK.checkpoints[s.pk.cp];
  const next = PK.checkpoints[s.pk.cp + 1] ?? PK.finish;
  tp(player, cp, { x: next.x, y: cp.y, z: next.z });
  s.pk.falls++;
}

function parkourTick(player, s) {
  const l = player.location;
  const pad = PK.startPad;
  const onStart = Math.abs(Math.floor(l.x) - pad.x) <= 1 && Math.abs(Math.floor(l.z) - pad.z) <= 1 && l.y >= LOBBY.y + 0.5 && l.y <= LOBBY.y + 2.5;
  if (!s.pk) {
    if (onStart && s.pad !== "parkour") startParkour(player);
    s.pad = onStart ? "parkour" : s.pad === "parkour" ? null : s.pad;
    return;
  }
  if (onStart) {
    s.pk.start = system.currentTick; // standing on the start pad: the clock restarts
    s.pk.cp = 0;
  }
  const near = (p) => Math.abs(l.x - p.x) <= 1.6 && Math.abs(l.z - p.z) <= 1.6 && l.y >= p.y - 0.6 && l.y <= p.y + 1.5;
  for (let i = s.pk.cp + 1; i < PK.checkpoints.length; i++) {
    if (near(PK.checkpoints[i])) {
      s.pk.cp = i;
      sound(player, "random.levelup", 0.6, 1.5);
      title(player, "§a§lPUNTO DE CONTROL", `§f${i}/${PK.checkpoints.length - 1} §7· ${fmtMs(system.currentTick - s.pk.start)}`, 25);
    }
  }
  const time = system.currentTick - s.pk.start;
  if (near(PK.finish)) {
    const best = STATS[player.name]?.pk;
    const record = !best || time < best;
    if (record) {
      (STATS[player.name] ??= {}).pk = time;
      statsDirty = true;
    }
    title(player, "§6§l¡PARKOUR COMPLETADO!", `§f${fmtMs(time)}${record ? " §a¡nuevo récord!" : ` §7(récord: ${fmtMs(best)})`}`, 70);
    sound(player, "random.totem", 0.6, 1.2);
    world.sendMessage(`§2[Parkour]§r §e${player.name}§r llegó a la cima del Árbol del Mundo en §e${fmtMs(time)}§r${record ? " §a(¡su mejor tiempo!)" : ""}.`);
    stopParkour(player);
    return;
  }
  const cp = PK.checkpoints[s.pk.cp];
  if (s.pk.cp > 0 && l.y < cp.y - 4) toCheckpoint(player);
  else if (Math.hypot(l.x - pad.x, l.z - pad.z) > 45 && l.y < LOBBY.y + 6) stopParkour(player, "§2[Parkour]§r Te alejaste del recorrido: parkour cancelado.");
  else bar(player, `§2Parkour §f${fmtMs(time)} §7| punto de control §f${s.pk.cp}/${PK.checkpoints.length - 1}`);
}

// ------------------------------------------------------------ Emparejamiento (1v1)
const duel = { queue: [], matches: [] }; // matches[i] = match on map i

function freeDuelMaps() {
  return DUELS.map((_, i) => i).filter((i) => S.duel.maps[i] !== false && !duel.matches[i] && built(DUELS[i].id));
}

function duelJoin(player) {
  if (!S.duel.enabled) return player.sendMessage("§c[Emparejamiento] El modo está desactivado por un administrador.");
  if (!DUELS.some((d) => built(d.id))) return player.sendMessage("§e[Emparejamiento] Las arenas se están construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  if (duel.queue.includes(player.id)) return player.sendMessage("§e[Emparejamiento] Ya estás en la cola.");
  leaveQueues(player);
  duel.queue.push(player.id);
  sound(player, "random.orb", 0.7, 1.2);
  player.sendMessage(`§b[Emparejamiento]§r Entraste a la cola §7(${duel.queue.length} en cola)§r. Buscando rival...`);
}

function duelLeave(player) {
  const i = duel.queue.indexOf(player.id);
  if (i < 0) return;
  duel.queue.splice(i, 1);
  player.sendMessage("§b[Emparejamiento]§r Saliste de la cola.");
}

function duelShots(map, spawns, names) {
  const c = { x: map.cx + 0.5, y: DUEL.y + 3, z: map.cz + 0.5 };
  const face = (sp, other) => {
    const dx = other.x - sp.x, dz = other.z - sp.z, d = Math.hypot(dx, dz);
    return { pos: { x: sp.x + (dx / d) * 3.6, y: sp.y + 1.9, z: sp.z + (dz / d) * 3.6 }, look: { x: sp.x, y: sp.y + 1.6, z: sp.z } };
  };
  const a = face(spawns[0], spawns[1]), b = face(spawns[1], spawns[0]);
  return () => [
    { pos: { x: c.x - 44, y: c.y + 46, z: c.z - 44 }, look: c, hold: 0 },
    { pos: { x: c.x + 42, y: c.y + 26, z: c.z - 30 }, look: c, ease: 3, hold: 0.2, title: `§b§l${map.name.toUpperCase()}`, sub: "§fEmparejamiento · 1 contra 1" },
    { ...a, ease: 1.8, hold: 0.4, title: `§e§l${names[0]}`, sub: "§7kit de diamante encantado" },
    { ...b, ease: 1.8, hold: 0.6, title: `§fVS §e§l${names[1]}`, sub: "§7¡que gane el mejor!" },
  ];
}

function startDuel(i, a, b) {
  const map = DUELS[i];
  const spawns = map.spawns();
  const m = { i, ids: [a.id, b.id], names: [a.name, b.name], spawns, phase: "intro", t: S.duel.countdown, time: 0 };
  duel.matches[i] = m;
  [a, b].forEach((p, k) => {
    const s = st(p);
    stopParkour(p);
    s.mode = "duel";
    s.match = m;
    s.pad = null;
    setMode(p, GM.adventure);
    heal(p);
    tp(p, spawns[k]);
    giveKit(p, getKit("duel"));
    lockEffects(p, 60);
    modeMusic(p);
    p.sendMessage(`§b[Emparejamiento]§r Rival: §e${k ? a.name : b.name}§r · mapa: §b${map.name}§r.`);
  });
  const go = () => {
    if (m.phase !== "intro") return;
    m.phase = "countdown";
  };
  if (S.duel.cinematic) cinematic([a, b], duelShots(map, spawns, m.names)).then(go);
  else go();
}

function duelPlayers(m) {
  return m.ids.map(byId);
}

function endDuel(m, winnerIdx, reason) {
  if (m.phase === "end") return;
  m.phase = "end";
  const players = duelPlayers(m);
  if (winnerIdx === undefined) {
    for (const p of players) if (p) title(p, "§e§lEMPATE", reason ?? "");
    world.sendMessage(`§b[Emparejamiento]§r §e${m.names[0]}§r y §e${m.names[1]}§r empataron.`);
  } else {
    const w = players[winnerIdx], l = players[1 - winnerIdx];
    addStat(m.names[winnerIdx], "dw");
    addStat(m.names[1 - winnerIdx], "dl");
    if (w) {
      title(w, "§a§l¡VICTORIA!", `§fderrotaste a §e${m.names[1 - winnerIdx]}`);
      sound(w, "random.levelup");
      unlock(w);
      effect(w, "resistance", 5, 255);
    }
    if (l) title(l, "§c§lDERROTA", `§fte ganó §e${m.names[winnerIdx]}`);
    world.sendMessage(`§b[Emparejamiento]§r §a${m.names[winnerIdx]}§r ganó a §c${m.names[1 - winnerIdx]}§r en §b${DUELS[m.i].name}§r${reason ? ` §7(${reason})` : ""}.`);
  }
  for (const id of m.ids) {
    const s = P.get(id);
    if (s?.match === m) s.match = undefined;
  }
  system.runTimeout(() => {
    for (const p of duelPlayers(m)) if (p && st(p).mode === "duel") sendToLobby(p);
    if (duel.matches[m.i] === m) duel.matches[m.i] = undefined;
  }, 3 * SEC);
}

function duelTick() {
  // matchmaking
  duel.queue = duel.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby");
  if (S.duel.enabled) {
    while (duel.queue.length >= 2) {
      const free = freeDuelMaps();
      if (!free.length) {
        for (const id of duel.queue) bar(byId(id), "§bEmparejamiento: §fesperando a que se libere una arena...");
        break;
      }
      const i = free.includes(S.duel.nextMap) ? S.duel.nextMap : randOf(free);
      const a = byId(duel.queue.shift()), b = byId(duel.queue.shift());
      startDuel(i, a, b);
    }
    if (duel.queue.length === 1) bar(byId(duel.queue[0]), "§bEmparejamiento: §fbuscando rival...");
  }
  for (const m of duel.matches) {
    if (!m || m.phase === "end" || m.phase === "intro") continue;
    const players = duelPlayers(m);
    if (m.phase === "countdown") {
      if (m.t > 0) {
        for (const p of players) {
          if (!p) continue;
          const c = m.t <= 2 ? "§c" : m.t <= 3 ? "§6" : "§e";
          title(p, `${c}§l${m.t}`, "§7prepárate", 16);
          sound(p, "note.pling", 0.8, m.t <= 3 ? 1.5 : 1);
        }
        m.t--;
      } else {
        m.phase = "fight";
        for (const p of players) {
          if (!p) continue;
          unlock(p);
          title(p, "§a§l¡A PELEAR!", "", 20);
          sound(p, "mob.enderdragon.growl", 0.4, 1.3);
        }
      }
    } else if (m.phase === "fight") {
      m.time++;
      const left = S.duel.maxTime > 0 ? S.duel.maxTime - m.time : undefined;
      for (const p of players) if (p) bar(p, `§b⚔ §f${m.names[0]} §7vs §f${m.names[1]}${left !== undefined ? `  §7| §e${fmtTime(left)}` : ""}`);
      if (left !== undefined && left <= 0) endDuel(m, undefined, "se acabó el tiempo");
    }
  }
}

// ------------------------------------------------------------ Caza (hunt)
const hunt = {
  phase: "idle", queue: [], countdown: 0, map: 0, hunted: undefined, hunters: [], alive: new Set(), spectators: new Set(),
  names: {}, timeLeft: 0, headLeft: 0, released: 0, finalDuel: false, lastStand: false, placed: new Set(), nextHunted: undefined,
};
const huntMap = () => HUNTS[hunt.map];

function huntJoin(player) {
  if (!S.hunt.enabled) return player.sendMessage("§c[Caza] El modo está desactivado por un administrador.");
  if (!HUNTS.some((m) => built(m.id))) return player.sendMessage("§e[Caza] Los mapas de caza se están construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  if (hunt.queue.includes(player.id)) return player.sendMessage("§e[Caza] Ya estás en la cola.");
  if (hunt.phase === "running" || hunt.phase === "ending") return player.sendMessage("§e[Caza] Hay una caza en curso. Entra a la cola cuando acabe, o mírala como espectador desde el menú.");
  if (hunt.queue.length >= S.hunt.maxPlayers) return player.sendMessage(`§c[Caza] La caza está llena (${S.hunt.maxPlayers}/${S.hunt.maxPlayers}).`);
  leaveQueues(player);
  hunt.queue.push(player.id);
  sound(player, "random.orb", 0.7, 0.9);
  for (const id of hunt.queue) byId(id)?.sendMessage(`§c[Caza]§r §e${player.name}§r entró a la caza §7(${hunt.queue.length}/${S.hunt.maxPlayers})`);
}

function huntLeave(player) {
  const i = hunt.queue.indexOf(player.id);
  if (i < 0) return;
  hunt.queue.splice(i, 1);
  player.sendMessage("§c[Caza]§r Saliste de la cola.");
}

function huntSpectate(player) {
  if (hunt.phase !== "running") return player.sendMessage("§e[Caza] No hay ninguna caza en curso.");
  leaveQueues(player);
  stopParkour(player);
  const s = st(player);
  s.mode = "hunt_spec";
  hunt.spectators.add(player.id);
  clearPlayer(player);
  setMode(player, GM.spectator);
  const target = byId(hunt.hunted);
  tp(player, target ? { x: target.location.x, y: target.location.y + 12, z: target.location.z } : huntCenter());
  player.sendMessage("§c[Caza]§r Estás mirando la caza. Usa §e/natura:lobby§r para volver.");
  huntMusicJoin(player);
}

function huntCenter() {
  const m = huntMap();
  const s = m.surface(m.cx, m.cz);
  return { x: m.cx + 0.5, y: s.y + 25, z: m.cz + 0.5 };
}

function randomSpot(awayFrom, minDist) {
  const m = huntMap();
  let best, bestD = -1;
  for (let i = 0; i < 120; i++) {
    const x = m.x0 + 14 + Math.floor(Math.random() * (HUNT.size - 28));
    const z = m.z0 + 14 + Math.floor(Math.random() * (HUNT.size - 28));
    const s = m.surface(x, z);
    if (!s.safe) continue;
    const loc = { x: x + 0.5, y: s.y, z: z + 0.5 };
    const d = awayFrom ? Math.sqrt(dist2(loc, awayFrom)) : 1e9;
    if (d >= minDist) return loc;
    if (d > bestD) {
      best = loc;
      bestD = d;
    }
  }
  return best ?? huntCenter();
}

function huntParticipants() {
  return [hunt.hunted, ...hunt.hunters, ...hunt.spectators].map(byId).filter(Boolean);
}

function aliveHunters() {
  return hunt.hunters.filter((id) => hunt.alive.has(id));
}

// Loot for the chests of the structures (both sides can take it).
const LOOT = [
  [8, () => ({ id: "minecraft:arrow", count: 8 + Math.floor(Math.random() * 9) })],
  [5, () => ({ id: "minecraft:ender_pearl", count: 1 + Math.floor(Math.random() * 2) })],
  [6, () => ({ id: "minecraft:golden_apple", count: 1 + Math.floor(Math.random() * 2) })],
  [6, () => ({ id: "minecraft:web|minecraft:cobweb", count: 4 + Math.floor(Math.random() * 5), placeOn: "ground" })],
  [6, () => ({ id: "minecraft:snowball", count: 8 + Math.floor(Math.random() * 9) })],
  [5, () => ({ id: "minecraft:golden_carrot", count: 4 })],
  [4, () => ({ id: "minecraft:ladder", count: 6, placeOn: "wood" })],
  [3, () => ({ id: "minecraft:fishing_rod" })],
  [3, () => ({ id: "minecraft:scaffolding", count: 8, placeOn: "ground" })],
  [1, () => ({ id: "minecraft:enchanted_golden_apple" })],
  [1, () => ({ id: "minecraft:totem_of_undying" })],
];

function lootRoll() {
  const total = LOOT.reduce((a, [w]) => a + w, 0);
  let r = Math.random() * total;
  for (const [w, f] of LOOT) if ((r -= w) <= 0) return f();
  return LOOT[0][1]();
}

function fillChests(map) {
  const marks = map.chests();
  const sections = new Map();
  for (const c of marks) {
    const k = `${Math.floor(c.x / 160)},${Math.floor(c.z / 160)}`;
    if (!sections.has(k)) sections.set(k, []);
    sections.get(k).push(c);
  }
  for (const list of sections.values()) {
    const xs = list.map((c) => c.x), zs = list.map((c) => c.z);
    withArea(Math.min(...xs), Math.min(...zs), Math.max(...xs), Math.max(...zs), (dim) => {
      for (const c of list) {
        try {
          const block = dim.getBlock({ x: c.x, y: c.y, z: c.z });
          if (!block) continue;
          block.setPermutation(mc.BlockPermutation.resolve("minecraft:chest", { "minecraft:cardinal_direction": c.dir ?? "south" }));
          const inv = block.getComponent("minecraft:inventory")?.container;
          if (!inv) continue;
          inv.clearAll();
          const n = 3 + Math.floor(Math.random() * 3);
          for (let i = 0; i < n; i++) {
            const item = makeItem(lootRoll());
            if (item) inv.setItem(Math.floor(Math.random() * inv.size), item);
          }
        } catch {}
      }
    });
  }
}

function startHunt() {
  const ids = hunt.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby").slice(0, S.hunt.maxPlayers);
  hunt.queue = [];
  if (ids.length < 2) return;
  const maps = HUNTS.map((_, i) => i).filter((i) => S.hunt.maps[i] !== false && built(HUNTS[i].id));
  if (!maps.length) return;
  hunt.map = maps.includes(S.hunt.nextMap) ? S.hunt.nextMap : randOf(maps);
  const map = huntMap();
  const huntedId = ids.includes(hunt.nextHunted) ? hunt.nextHunted : ids[Math.floor(Math.random() * ids.length)];
  hunt.nextHunted = undefined;
  hunt.hunted = huntedId;
  hunt.hunters = shuffle(ids.filter((id) => id !== huntedId));
  hunt.alive = new Set(ids);
  hunt.spectators = new Set();
  hunt.names = Object.fromEntries(ids.map((id) => [id, byId(id).name]));
  hunt.timeLeft = S.hunt.timeLimit;
  hunt.headLeft = S.hunt.headStart;
  hunt.released = 0;
  hunt.finalDuel = false;
  hunt.lastStand = false;
  hunt.intro = true;
  hunt.phase = "running";
  if (S.hunt.chests) fillChests(map);

  const preyLoc = randomSpot(undefined, 0);
  const packLoc = randomSpot(preyLoc, 170);
  const kit = scaledHuntedKit(hunt.hunters.length);
  const prey = byId(huntedId);
  const s = st(prey);
  stopParkour(prey);
  s.mode = "hunt";
  s.role = "hunted";
  s.pad = null;
  s.lockAt = preyLoc;
  setMode(prey, GM.adventure);
  heal(prey);
  tp(prey, preyLoc);
  giveKit(prey, kit);
  system.runTimeout(() => {
    try {
      if (valid(prey)) prey.getComponent("minecraft:health")?.resetToMaxValue();
    } catch {}
  }, 2);
  lockEffects(prey, 60);
  prey.sendMessage(`§c[Caza]§r Eres el §ccazado§r en §6${map.name}§r. Tu kit de hierro tiene §e+${kit.bonus}§r de mejora por los ${hunt.hunters.length} cazadores. Ventaja: §e${S.hunt.headStart} s§r. Las estructuras tienen escaleras y cofres con botín.`);
  hunt.hunters.forEach((id, k) => {
    const p = byId(id);
    const hs = st(p);
    stopParkour(p);
    hs.mode = "hunt";
    hs.role = "hunter";
    hs.pad = null;
    setMode(p, GM.adventure);
    heal(p);
    const a = (k / hunt.hunters.length) * Math.PI * 2;
    hs.lockAt = { x: packLoc.x + Math.cos(a) * 2, y: packLoc.y, z: packLoc.z + Math.sin(a) * 2 };
    tp(p, hs.lockAt, preyLoc);
    giveKit(p, getKit("hunter"));
    lockEffects(p, 60);
    p.sendMessage(`§c[Caza]§r Eres §acazador§r en §6${map.name}§r. Atrapa a §c${hunt.names[huntedId]}§r antes de §e${fmtTime(S.hunt.timeLimit)}§r.`);
  });
  world.sendMessage(`§c[Caza]§r ¡Empieza la caza en §6${map.name}§r! §c${hunt.names[huntedId]}§r contra ${hunt.hunters.map((id) => `§a${hunt.names[id]}`).join("§r, ")}§r.`);
  // the music the hunted player chose plays for everybody in the hunt
  const preyPrefs = prefs(prey);
  huntMusicStart(S.hunt.music ? queueOf(preyPrefs.hunt) : []);
  if (S.hunt.music) {
    const desc = describePlaylist(preyPrefs.hunt);
    for (const p of huntParticipants()) p.sendMessage(`§d♪ Música de ${prey.name}: §f${desc}`);
  }
  const release = () => {
    hunt.intro = false;
    if (hunt.phase !== "running") return;
    const p0 = byId(hunt.hunted);
    if (p0) {
      unlock(p0);
      st(p0).lockAt = undefined;
      title(p0, "§c§l¡CORRE!", `§f${hunt.hunters.length} cazador(es) salen en §e${hunt.headLeft} s`, 40);
      sound(p0, "mob.wither.spawn", 0.5, 1.2);
    }
    for (const id of aliveHunters()) {
      const p = byId(id);
      if (!p) continue;
      if (hunt.headLeft > 0) effect(p, "blindness", hunt.headLeft + 1, 0);
      else unlock(p);
      title(p, "§a§lERES CAZADOR", `§fsales en §e${hunt.headLeft} s`, 40);
    }
    checkMusic();
  };
  if (S.hunt.cinematic) {
    cinematic(huntParticipants(), (p) => {
      const l = p.location;
      const prey_ = p.id === hunt.hunted;
      const eye = { x: l.x, y: l.y + 1.6, z: l.z };
      return [
        { pos: { x: l.x + 34, y: l.y + 40, z: l.z + 34 }, look: eye, hold: 0 },
        { pos: { x: l.x - 30, y: l.y + 22, z: l.z + 26 }, look: eye, ease: 3.2, hold: 0.2, title: `§6§l${map.name.toUpperCase()}`, sub: `§fCaza · ${map.desc}` },
        { pos: { x: l.x + 3, y: l.y + 2.2, z: l.z + 3 }, look: eye, ease: 2, hold: 0.8, title: prey_ ? "§c§lERES EL CAZADO" : "§a§lERES CAZADOR", sub: prey_ ? `§f${hunt.hunters.length} cazador(es) te buscan` : `§fatrapa a §c${hunt.names[hunt.hunted]}` },
      ];
    }).then(release);
  } else release();
}

// Only the hunted and one hunter left: the final duel (and its song).
function checkMusic() {
  if (hunt.phase !== "running" || hunt.finalDuel || hunt.intro) return;
  if (!hunt.alive.has(hunt.hunted) || aliveHunters().length !== 1) return;
  hunt.finalDuel = true;
  const prey = byId(hunt.hunted);
  const fin = prey ? prefs(prey).final : 0;
  if (S.hunt.music && validTrack(fin)) huntMusicStart([fin]);
  for (const p of huntParticipants()) {
    title(p, "§4§l¡DUELO FINAL!", `§c${hunt.names[hunt.hunted]} §7contra §a${hunt.names[aliveHunters()[0]]}`, 50);
  }
}

function forceLastStand(admin) {
  if (hunt.phase !== "running") return admin.sendMessage("§c[Admin] No hay ninguna caza en curso.");
  const secs = Math.max(1, S.hunt.lastStandMinutes) * 60;
  hunt.lastStand = true;
  hunt.timeLeft = Math.min(hunt.timeLeft, secs);
  const name = hunt.names[hunt.hunted];
  for (const p of huntParticipants()) {
    title(p, "§4§lÚLTIMO EN PIE", `§flos cazadores tienen §e${fmtTime(hunt.timeLeft)}§f para atrapar a §c${name}`, 70);
    sound(p, "mob.enderdragon.growl", 0.6, 0.8);
  }
  world.sendMessage(`§c[Caza]§r §4§lÚltimo en pie:§r los cazadores tienen §e${fmtTime(hunt.timeLeft)}§r para atrapar a §c${name}§r. Si no, gana el cazado.`);
}

function huntEliminate(id, killerName, reason) {
  if (hunt.phase !== "running" || !hunt.alive.has(id)) return;
  hunt.alive.delete(id);
  const name = hunt.names[id];
  for (const p of huntParticipants()) {
    p.sendMessage(`§c[Caza]§r ${id === hunt.hunted ? "§c" : "§a"}${name}§r ${reason ?? (killerName ? `fue eliminado por §e${killerName}` : "fue eliminado")}§r.`);
  }
  if (id === hunt.hunted) return endHunt("hunters", killerName ? `${killerName} atrapó a ${name}` : `${name} cayó`);
  addStat(name, "hl");
  const s = P.get(id);
  if (s) {
    s.mode = "hunt_spec";
    hunt.spectators.add(id);
  }
  if (aliveHunters().length === 0) return endHunt("hunted", "todos los cazadores cayeron");
  checkMusic();
}

// Puts back the columns where players placed cobwebs, ladders or scaffolding.
function cleanPlaced() {
  if (!hunt.placed.size) return;
  const keys = new Set([...hunt.placed].map((k) => k.split(",").filter((_, i) => i !== 1).join(",")));
  const id = huntMap().id;
  hunt.placed.clear();
  world.setDynamicProperty("natura:huntPlaced", undefined);
  rebuildColumns(id, keys, "Limpiando la caza");
}

function savePlaced() {
  world.setDynamicProperty("natura:huntPlaced", JSON.stringify({ map: huntMap().id, keys: [...hunt.placed].slice(0, 2000) }));
}

function endHunt(winner, reason) {
  if (hunt.phase !== "running") return;
  hunt.phase = "ending";
  const preyName = hunt.names[hunt.hunted];
  const winners = winner === "hunted" ? [hunt.hunted] : hunt.hunters;
  for (const id of winners) addStat(hunt.names[id], "hw");
  if (winner === "hunters") addStat(preyName, "hl");
  for (const p of huntParticipants()) {
    const won = winners.includes(p.id);
    title(p, winner === "hunted" ? "§c§lGANA EL CAZADO" : "§a§lGANAN LOS CAZADORES", `§f${reason}`, 70);
    if (won) sound(p, "random.levelup");
    unlock(p);
    effect(p, "resistance", 8, 255);
  }
  world.sendMessage(`§c[Caza]§r ${winner === "hunted" ? `§c${preyName}§r sobrevivió a la caza` : `Los cazadores atraparon a §c${preyName}§r`} §7(${reason})§r.`);
  system.runTimeout(() => {
    huntMusicStop();
    const m = huntMap();
    for (const type of ["item", "arrow", "snowball", "ender_pearl", "fishing_hook"]) {
      cmd(`kill @e[type=${type},x=${m.x0},y=${HUNT.floor},z=${m.z0},dx=${HUNT.size},dy=${HUNT.clearTop - HUNT.floor},dz=${HUNT.size}]`);
    }
    for (const p of huntParticipants()) {
      const mode = st(p).mode;
      if (mode === "hunt" || mode === "hunt_spec") sendToLobby(p);
    }
    cleanPlaced();
    hunt.phase = "idle";
    hunt.hunted = undefined;
    hunt.hunters = [];
    hunt.alive.clear();
    hunt.spectators.clear();
    hunt.finalDuel = false;
    hunt.lastStand = false;
  }, 6 * SEC);
}

function huntTick() {
  if (hunt.phase === "idle" || hunt.phase === "countdown") {
    hunt.queue = hunt.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby");
    const n = hunt.queue.length;
    if (!S.hunt.enabled || n < Math.max(2, S.hunt.minPlayers)) {
      hunt.phase = "idle";
      for (const id of hunt.queue) bar(byId(id), `§cCaza: §fesperando jugadores §7(${n}/${S.hunt.maxPlayers}, mínimo ${Math.max(2, S.hunt.minPlayers)})`);
      return;
    }
    if (hunt.phase === "idle") {
      hunt.phase = "countdown";
      hunt.countdown = S.hunt.lobbyCountdown;
    }
    if (n >= S.hunt.maxPlayers) hunt.countdown = Math.min(hunt.countdown, 5);
    for (const id of hunt.queue) {
      const p = byId(id);
      bar(p, `§cCaza: §fempieza en §e${hunt.countdown}s §7(${n}/${S.hunt.maxPlayers})`);
      if (hunt.countdown <= 5) sound(p, "note.hat", 0.7, 1.4);
    }
    if (hunt.countdown-- <= 0) startHunt();
    return;
  }
  if (hunt.phase !== "running") return;
  // players that left
  for (const id of [...hunt.alive]) if (!byId(id)) huntEliminate(id, undefined, "abandonó la partida");
  if (hunt.phase !== "running" || hunt.intro) return;
  const prey = byId(hunt.hunted);
  if (hunt.headLeft > 0) {
    hunt.headLeft--;
    if (hunt.headLeft === 0) {
      for (const id of aliveHunters()) {
        const p = byId(id);
        unlock(p);
        title(p, "§a§l¡A CAZAR!", `§fencuentra a §c${hunt.names[hunt.hunted]}`, 30);
        sound(p, "mob.wolf.howl", 1, 0.9);
        st(p).lockAt = undefined;
      }
      if (prey) {
        title(prey, "§c§l¡YA VIENEN!", "", 30);
        sound(prey, "mob.wolf.howl", 1, 0.9);
      }
    }
  } else hunt.released++;
  hunt.timeLeft--;
  const every = hunt.lastStand ? (S.hunt.reveal > 0 ? Math.min(S.hunt.reveal, 30) : 30) : S.hunt.reveal;
  if (every > 0 && hunt.released > 0 && hunt.released % every === 0 && prey) {
    const l = prey.location;
    for (const id of aliveHunters()) {
      const p = byId(id);
      p.sendMessage(`§c[Caza]§r §c${prey.name}§r fue visto en §eX ${Math.round(l.x)}  Y ${Math.round(l.y)}  Z ${Math.round(l.z)}`);
      sound(p, "note.bell", 1, 1.2);
    }
    prey.sendMessage("§c[Caza]§r ¡Los cazadores han visto tu posición!");
    sound(prey, "note.bass", 1, 0.6);
  }
  // HUD
  const hn = aliveHunters().length;
  for (const p of huntParticipants()) {
    const s = st(p);
    let text;
    if (p.id === hunt.hunted) text = `§cCAZADO §7| §fcazadores: §a${hn} §7| §e${fmtTime(hunt.timeLeft)}`;
    else if (s.mode === "hunt" && prey) {
      const d = Math.round(Math.sqrt(dist2(p.location, prey.location)));
      text = hunt.headLeft > 0 ? `§aCAZADOR §7| §fsales en §e${hunt.headLeft}s` : `§aCAZADOR §7| §fpresa: §c${hunt.names[hunt.hunted]} §7~${d > 100 ? "+100" : Math.ceil(d / 10) * 10} bloques §7| §e${fmtTime(hunt.timeLeft)}`;
    } else text = `§7ESPECTADOR §7| §fcazadores: §a${hn} §7| §e${fmtTime(hunt.timeLeft)}`;
    bar(p, hunt.lastStand ? `§4ÚLTIMO EN PIE §7| ${text}` : text);
  }
  if (hunt.timeLeft <= 0) endHunt("hunted", "sobrevivió hasta el final del tiempo");
}

// ------------------------------------------------------------ Campal
const OBJ = "natura_campal";

function campalObjective() {
  return world.scoreboard.getObjective(OBJ) ?? world.scoreboard.addObjective(OBJ, "§a§lCampal §r§7· bajas");
}

function campalSidebar() {
  try {
    const slot = enumv(mc.DisplaySlotId, "Sidebar");
    if (S.campal.sidebar) world.scoreboard.setObjectiveAtDisplaySlot(slot, { objective: campalObjective(), sortOrder: enumv(mc.ObjectiveSortOrder, "Descending") });
    else world.scoreboard.clearObjectiveAtDisplaySlot(slot);
  } catch {}
}

function campalPlayers() {
  return world.getPlayers().filter((p) => st(p).mode === "campal");
}

function campalEnter(player) {
  if (!S.campal.enabled) return player.sendMessage("§c[Campal] La arena está cerrada por un administrador.");
  if (!built("campal")) return player.sendMessage("§e[Campal] La arena se está construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  leaveQueues(player);
  stopParkour(player);
  st(player).mode = "campal";
  spawnInCampal(player, true);
  modeMusic(player);
  world.sendMessage(`§a[Campal]§r §e${player.name}§r entró a la arena §7(${campalPlayers().length} dentro)`);
}

function spawnInCampal(player, first) {
  const others = campalPlayers().filter((p) => p.id !== player.id).map((p) => p.location);
  let best, bestD = -1;
  for (const sp of campalSpawns()) {
    const d = others.length ? Math.min(...others.map((o) => dist2(o, sp))) : Math.random();
    if (d > bestD) {
      best = sp;
      bestD = d;
    }
  }
  const s = st(player);
  s.pad = null;
  setMode(player, GM.adventure);
  heal(player);
  tp(player, best);
  giveKit(player, getKit("campal"));
  player.getComponent("minecraft:inventory")?.container?.setItem(8, ITEMS.leave());
  if (S.campal.spawnProtection > 0) effect(player, "resistance", S.campal.spawnProtection, 255);
  title(player, "§a§lCAMPAL", first ? "§fla arena siempre está activa" : "§f¡de vuelta a la pelea!", 30);
  try {
    const obj = campalObjective();
    if (!obj.hasParticipant(player)) obj.setScore(player, 0);
  } catch {}
}

function campalLeave(player) {
  if (inCombat(player)) {
    const left = Math.ceil((S.campal.combatTag * SEC - (system.currentTick - st(player).hurtTick)) / SEC);
    return player.sendMessage(`§c[Campal] Estás en combate. Espera ${left} s sin recibir daño para salir.`);
  }
  sendToLobby(player, "§a[Campal]§r Volviste al lobby.");
}

// ------------------------------------------------------------ deaths, damage, leaving
function killerOf(player, source) {
  let k = source?.damagingEntity;
  if (k?.typeId !== "minecraft:player") k = undefined;
  const s = st(player);
  if (!k && s.attacker && system.currentTick - s.attackerTick < 15 * SEC) k = byId(s.attacker);
  return k?.id !== player.id ? k : undefined;
}

world.afterEvents.entityDie.subscribe(({ deadEntity: player, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const killer = killerOf(player, damageSource);
  addStat(player, "d");
  if (killer) addStat(killer, "k");
  s.attacker = undefined;
  if (s.mode === "duel" && s.match) {
    const m = s.match;
    const idx = m.ids.indexOf(player.id);
    s.mode = "lobby";
    endDuel(m, 1 - idx, m.phase !== "fight" ? "murió antes de empezar" : undefined);
  } else if (s.mode === "hunt") {
    huntEliminate(player.id, killer?.name);
  } else if (s.mode === "campal") {
    if (killer && st(killer).mode === "campal") {
      addStat(killer, "ck");
      try {
        campalObjective().addScore(killer, 1);
      } catch {}
      if (S.campal.reward) {
        effect(killer, "regeneration", 4, 2);
        killer.getComponent("minecraft:inventory")?.container?.addItem(new ItemStack("minecraft:golden_apple", 1));
      }
      bar(killer, `§a+1 baja §7(eliminaste a §f${player.name}§7)`);
      sound(killer, "random.orb", 1, 1.6);
    }
    for (const p of campalPlayers()) if (p.id !== player.id) p.sendMessage(`§a[Campal]§r §c${player.name}§r ${killer ? `fue eliminado por §a${killer.name}` : "murió"}§r.`);
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerSpawn.subscribe(({ player, initialSpawn }) => {
  const s = st(player);
  if (initialSpawn) {
    P.delete(player.id);
    system.runTimeout(() => {
      if (!valid(player)) return;
      camClear(player);
      hud(player, true);
      if (!built("lobby")) {
        tp(player, { x: 0.5, y: LOBBY.y + 6, z: LOBBY.spawn.z });
        effect(player, "slow_falling", 30, 0);
        return;
      }
      sendToLobby(player);
      title(player, "§2§lNATURA PvP", "§fbienvenido al Árbol del Mundo", 60);
      player.sendMessage("§2[Natura PvP]§r Usa la §abrújula§r (menú) o cruza una de las §6puertas de piedra§r: §bEmparejamiento§r, §cCaza§r o §aCampal§r. Mientras esperas, prueba el §2parkour§r (plataforma azul junto a la raíz).");
      if (isAdmin(player)) player.sendMessage("§7Eres administrador: usa el §creloj§7 o §f/natura:admin§7 para abrir el panel.");
    }, 10);
    return;
  }
  // respawn after dying
  system.runTimeout(() => {
    if (!valid(player)) return;
    if (s.mode === "campal" && S.campal.enabled) spawnInCampal(player, false);
    else if (s.mode === "hunt_spec" && hunt.phase === "running") {
      clearPlayer(player);
      setMode(player, GM.spectator);
      tp(player, huntCenter());
      player.sendMessage("§c[Caza]§r Ahora eres espectador. Usa §e/natura:lobby§r para volver al lobby.");
      huntMusicJoin(player);
    } else if (s.mode !== "free") sendToLobby(player);
  }, 2);
});

world.afterEvents.entityHurt.subscribe(({ hurtEntity: player, damage, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const attacker = damageSource?.damagingEntity;
  if (attacker?.typeId === "minecraft:player" && attacker.id !== player.id) {
    s.attacker = attacker.id;
    s.attackerTick = system.currentTick;
    s.hurtTick = system.currentTick;
    st(attacker).hurtTick = system.currentTick;
    // no friendly fire among hunters: give the health back
    if (s.mode === "hunt" && st(attacker).mode === "hunt" && s.role === "hunter" && st(attacker).role === "hunter" && !S.hunt.friendlyFire) {
      try {
        const h = player.getComponent("minecraft:health");
        if (h.currentValue > 0) h.setCurrentValue(Math.min(h.effectiveMax, h.currentValue + damage));
      } catch {}
    }
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerLeave.subscribe(({ playerId }) => {
  const s = P.get(playerId);
  const a = duel.queue.indexOf(playerId);
  if (a >= 0) duel.queue.splice(a, 1);
  const b = hunt.queue.indexOf(playerId);
  if (b >= 0) hunt.queue.splice(b, 1);
  hunt.spectators.delete(playerId);
  if (s?.mode === "duel" && s.match) {
    const m = s.match;
    endDuel(m, 1 - m.ids.indexOf(playerId), "el rival abandonó");
  }
  if (s?.mode === "hunt") huntEliminate(playerId, undefined, "abandonó la partida");
  P.delete(playerId);
  personal.delete(playerId);
  playing.delete(playerId);
});

// ------------------------------------------------------------ blocks
// Nobody breaks the map. In the hunt, the cobwebs, ladders and scaffolding the
// players place can be removed (and are cleaned when the hunt ends).
world.beforeEvents.playerBreakBlock.subscribe((ev) => {
  const s = P.get(ev.player.id);
  if (s?.mode === "free") return;
  const { x, y, z } = ev.block.location;
  if (s?.mode === "hunt" && hunt.placed.has(`${x},${y},${z}`)) return;
  ev.cancel = true;
});

world.afterEvents.playerBreakBlock.subscribe(({ block }) => {
  const { x, y, z } = block.location;
  if (hunt.placed.has(`${x},${y},${z}`)) hunt.placed.add(`${x},${y},${z}`); // stays listed: the column is rebuilt anyway
});

world.afterEvents.playerPlaceBlock.subscribe(({ block, player }) => {
  const s = P.get(player.id);
  if (s?.mode === "free") return;
  const { x, y, z } = block.location;
  if (s?.mode === "hunt" && huntMap().inside(x, z) && PLACEABLE.has(block.typeId) && y < HUNT.clearTop) {
    hunt.placed.add(`${x},${y},${z}`);
    savePlaced();
    return;
  }
  try {
    block.setType("minecraft:air");
  } catch {}
});

// ------------------------------------------------------------ items
world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (player?.typeId !== "minecraft:player") return;
  const kind = itemKind(itemStack);
  if (!kind) return;
  const s = st(player);
  if (system.currentTick - (s.lastUse ?? -99) < 8) return;
  s.lastUse = system.currentTick;
  if (kind === "selector") openSelector(player);
  else if (kind === "admin") openAdmin(player);
  else if (kind === "leave" && s.mode === "campal") campalLeave(player);
  else if (kind === "checkpoint") toCheckpoint(player);
});

// ------------------------------------------------------------ lobby: pads, texts, safety
const PADS = Object.entries(LOBBY.pads);

function padUnder(player) {
  const l = player.location;
  if (l.y < LOBBY.y + 0.5 || l.y > LOBBY.y + 2.5) return null;
  for (const [k, pad] of PADS) if (Math.abs(Math.floor(l.x) - pad.x) <= 1 && Math.abs(Math.floor(l.z) - pad.z) <= 1) return k;
  return null;
}

function padAction(player, key) {
  if (key === "duel") duel.queue.includes(player.id) ? player.sendMessage("§b[Emparejamiento]§r Ya estás en la cola. Abre el menú para salir.") : duelJoin(player);
  else if (key === "hunt") hunt.queue.includes(player.id) ? player.sendMessage("§c[Caza]§r Ya estás en la cola. Abre el menú para salir.") : huntJoin(player);
  else if (key === "campal") campalEnter(player);
}

const TEXTS = {
  welcome: { x: 0.5, y: LOBBY.y + 4.2, z: LOBBY.spawn.z - 4 },
  duel: { x: LOBBY.pads.duel.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.duel.z + 0.5 },
  hunt: { x: LOBBY.pads.hunt.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.hunt.z + 0.5 },
  campal: { x: LOBBY.pads.campal.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.campal.z + 0.5 },
  parkour: { x: PK.startPad.x + 0.5, y: LOBBY.y + 3.6, z: PK.startPad.z + 0.5 },
};

function topLines(key) {
  const t = top(key);
  return t.length ? t.map(([n, s], i) => `§6${i + 1}. §f${n} §7(${s[key]})`).join("\n") : "§7sin partidas todavía";
}

function textFor(key) {
  if (key === "welcome") return "§2§lNATURA PvP\n§fel Árbol del Mundo\n§7usa la §abrújula§7 o cruza una puerta";
  if (key === "duel") {
    const busy = duel.matches.filter((m) => m).length;
    return `§b§lEMPAREJAMIENTO\n§71 contra 1 · ${DUELS.length} mapas\n§fen cola: §e${duel.queue.length} §7| §fduelos: §e${busy}\n${S.duel.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("dw")}`;
  }
  if (key === "hunt") {
    const state = hunt.phase === "running" ? `§ccaza en curso §7(${huntMap().name})` : `§fen cola: §e${hunt.queue.length}/${S.hunt.maxPlayers}`;
    return `§c§lCAZA\n§7hasta ${S.hunt.maxPlayers} jugadores · ${HUNTS.length} mapas\n${state}\n${S.hunt.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("hw")}`;
  }
  if (key === "parkour") {
    const t = topParkour(3);
    return `§2§lPARKOUR\n§7sube al Árbol del Mundo\n§6Mejores tiempos\n${t.length ? t.map(([n, s], i) => `§6${i + 1}. §f${n} §7(${fmtMs(s.pk)})`).join("\n") : "§7nadie lo ha terminado aún"}`;
  }
  return `§a§lCAMPAL\n§7siempre abierta · entra cuando quieras\n§fdentro: §e${campalPlayers().length}\n${S.campal.enabled ? "" : "§c(cerrado)\n"}§6Top bajas\n${topLines("ck")}`;
}

function updateTexts() {
  const dim = overworld();
  try {
    if (!dim.getBlock({ x: 0, y: LOBBY.y, z: 0 })) return;
  } catch {
    return;
  }
  let all = [];
  try {
    all = dim.getEntities({ type: "natura:text" });
  } catch {
    return;
  }
  for (const [key, loc] of Object.entries(TEXTS)) {
    const tag = `natura_text_${key}`;
    const mine = all.filter((e) => e.hasTag(tag));
    let e = mine.shift();
    for (const extra of mine) extra.remove();
    if (!e) {
      try {
        e = dim.spawnEntity("natura:text", loc);
        e.addTag(tag);
      } catch {
        continue;
      }
    }
    const text = textFor(key);
    if (e.nameTag !== text) e.nameTag = text;
    if (dist2(e.location, loc) > 0.1 || Math.abs(e.location.y - loc.y) > 0.1) e.teleport(loc);
  }
}

// ------------------------------------------------------------ the main loop
let tick = 0;
system.runInterval(() => {
  tick++;
  const slow = tick % 8 === 0;
  for (const player of world.getPlayers()) {
    const s = st(player);
    const l = player.location;
    if (s.mode === "lobby") {
      if (!built("lobby")) {
        if (l.y < LOBBY.y - 4) tp(player, { x: 0.5, y: LOBBY.y + 6, z: LOBBY.spawn.z });
        effect(player, "slow_falling", 5, 0);
        continue;
      }
      if (l.y < LOBBY.y - 20 || Math.hypot(l.x, l.z) > LOBBY.radius + 6) {
        if (s.pk) toCheckpoint(player);
        else tp(player, LOBBY.spawn, LOBBY.look);
      }
      if (slow) {
        effect(player, "resistance", 12, 255);
        effect(player, "saturation", 12, 255);
        setMode(player, GM.adventure);
        const inv = player.getComponent("minecraft:inventory")?.container;
        if (inv) {
          if (itemKind(inv.getItem(0)) !== "selector") inv.setItem(0, ITEMS.selector());
          const has = itemKind(inv.getItem(8)) === "admin";
          if (isAdmin(player) && !has) inv.setItem(8, ITEMS.admin());
          if (!isAdmin(player) && has) inv.setItem(8, undefined);
          if (s.pk && itemKind(inv.getItem(4)) !== "checkpoint") inv.setItem(4, ITEMS.checkpoint());
        }
      }
      parkourTick(player, s);
      const pad = padUnder(player);
      if (pad && pad !== s.pad) padAction(player, pad);
      if (s.pad !== "parkour") s.pad = pad;
    } else if (s.mode === "duel" && s.match) {
      const sp = s.match.spawns[s.match.ids.indexOf(player.id)];
      if ((s.match.phase === "countdown" || s.match.phase === "intro") && dist2(l, sp) > 0.5) tp(player, sp);
      else if (l.y < DUEL.y - 3 || !insideArea(DUELS[s.match.i].id, l.x, l.z)) tp(player, sp);
    } else if (s.mode === "hunt") {
      const m = huntMap();
      if (s.lockAt && (hunt.intro || hunt.headLeft > 0) && dist2(l, s.lockAt) > 1) tp(player, s.lockAt);
      if (!m.inside(Math.floor(l.x), Math.floor(l.z)) || l.y < HUNT.floor) {
        const x = Math.max(m.x0 + 3, Math.min(m.x1 - 3, Math.floor(l.x)));
        const z = Math.max(m.z0 + 3, Math.min(m.z1 - 3, Math.floor(l.z)));
        tp(player, { x: x + 0.5, y: m.surface(x, z).y + 1, z: z + 0.5 });
      }
    } else if (s.mode === "hunt_spec") {
      if (!insideArea(huntMap().id, l.x, l.z, 20) || l.y > HUNT.clearTop + 60) tp(player, huntCenter());
    } else if (s.mode === "campal") {
      if (l.y < CAMPAL.y - 4 || !insideArea("campal", l.x, l.z)) spawnInCampal(player, false);
    } else if (s.mode === "free" && slow && isAdmin(player)) {
      const inv = player.getComponent("minecraft:inventory")?.container;
      if (inv && ![...Array(inv.size).keys()].some((i) => itemKind(inv.getItem(i)) === "admin")) inv.setItem(8, ITEMS.admin());
    }
  }
}, 5);

system.runInterval(() => {
  try {
    duelTick();
  } catch (e) {
    console.warn(`[Natura PvP] duelo: ${e}`);
  }
  try {
    huntTick();
  } catch (e) {
    console.warn(`[Natura PvP] caza: ${e}`);
  }
  if (progress.busy && progress.total > 2000) {
    const text = `§7Construyendo el mapa: §f${progress.label} §e${pct()}%`;
    for (const p of world.getPlayers()) if (isAdmin(p) || !built("lobby") || st(p).mode === "lobby") bar(p, text);
  }
}, SEC);

system.runInterval(updateTexts, 2 * SEC);

function pct() {
  return progress.total ? Math.floor((progress.done / progress.total) * 100) : 0;
}

// ------------------------------------------------------------ the map: prebuilt or built by the script
// The .mcworld comes with the whole map already built. If the packs are used in
// another world (or in a world from an older version), the script builds it.
async function ensureBuilt() {
  const ids = AREAS.map((a) => a.id);
  const marks = ids.map((id) => world.getDynamicProperty(`natura:built:${id}`));
  const fresh = marks.every((v) => v === undefined) && world.getDynamicProperty("natura:built:hunt") === undefined;
  if (fresh) {
    const id = await probe(LOBBY.marker.x, LOBBY.marker.y, LOBBY.marker.z);
    if (id && id !== "minecraft:air") {
      for (const a of ids) world.setDynamicProperty(`natura:built:${a}`, CFG.buildVersion);
      world.setDynamicProperty("natura:prebuilt", CFG.buildVersion);
      for (const p of world.getPlayers()) if (st(p).mode === "lobby") sendToLobby(p);
      return afterBuilt();
    }
  }
  const old = !fresh; // a world from an older version: rebuild over what is there
  for (const id of ids) {
    if (built(id)) continue;
    const ok = (await buildArea(id, old)) === true;
    if (ok) world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
    if (id === "lobby" && ok) {
      for (const p of world.getPlayers()) {
        if (st(p).mode !== "lobby") continue;
        sendToLobby(p);
        title(p, "§2§lNATURA PvP", "§fel mapa se está terminando de construir", 60);
      }
    }
    if (ok) world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name}: lista.`);
  }
  afterBuilt();
}

function afterBuilt() {
  // cobwebs and ladders left by a hunt that was cut short (the world closed)
  try {
    const left = JSON.parse(world.getDynamicProperty("natura:huntPlaced") ?? "null");
    if (left?.keys?.length && AREA[left.map]) {
      const keys = new Set(left.keys.map((k) => k.split(",").filter((_, i) => i !== 1).join(",")));
      rebuildColumns(left.map, keys, "Limpiando la caza");
    }
    world.setDynamicProperty("natura:huntPlaced", undefined);
  } catch {}
}

async function rebuild(id) {
  world.setDynamicProperty(`natura:built:${id}`, "rebuilding");
  const ok = (await buildArea(id, true)) === true;
  world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
  world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name}: reconstruida${ok ? "" : " (con errores)"}.`);
}

world.afterEvents.worldLoad.subscribe(() => {
  loadSettings();
  loadStats();
  applyGamerules();
  campalSidebar();
  ensureBuilt();
});

// ------------------------------------------------------------ menus
// buttons: [text, action, icon]. With `back`, a last button returns there.
async function menu(player, titleText, body, buttons, back) {
  const form = new ui.ActionFormData().title(titleText).body(body);
  const list = back ? [...buttons, ["§8« Volver", back, "textures/ui/arrow_left"]] : buttons;
  for (const [text, , icon] of list) form.button(text, icon);
  const r = await showForm(player, form);
  if (!r || r.canceled || !list[r.selection]) return;
  await list[r.selection][1]();
}

async function confirm(player, titleText, body) {
  const form = new ui.MessageFormData().title(titleText).body(body).button1("§a§lSí").button2("§cNo");
  const r = await showForm(player, form);
  return r && !r.canceled && r.selection === 0;
}

// ------------------------------------------------------------ the player menu
async function openSelector(player) {
  const s = st(player);
  if (s.mode === "campal") return campalLeave(player);
  if (s.mode !== "lobby") return openMusic(player);
  const inDuel = duel.queue.includes(player.id), inHuntQ = hunt.queue.includes(player.id);
  const best = STATS[player.name]?.pk;
  const queueText = inDuel ? "§bEstás en la cola de Emparejamiento." : inHuntQ ? "§cEstás en la cola de la Caza." : "§7No estás en ninguna cola.";
  const huntState = hunt.phase === "running" ? `en curso en ${huntMap().name} · mirar` : hunt.phase === "countdown" ? `empieza en ${hunt.countdown} s · ${hunt.queue.length}/${S.hunt.maxPlayers}` : `${hunt.queue.length}/${S.hunt.maxPlayers} en cola`;
  const buttons = [
    [inDuel ? "§c§lSALIR DE LA COLA\n§r§8Emparejamiento" : `§b§lEMPAREJAMIENTO\n§r§81 contra 1 · ${duel.queue.length} en cola`, () => (inDuel ? duelLeave(player) : duelJoin(player)), "textures/items/diamond_sword"],
    hunt.phase === "running"
      ? [`§c§lCAZA §r§8(en curso)\n§8mirar como espectador`, () => huntSpectate(player), "textures/items/bow_standby"]
      : [inHuntQ ? "§c§lSALIR DE LA COLA\n§r§8Caza" : `§c§lCAZA\n§r§8${huntState}`, () => (inHuntQ ? huntLeave(player) : huntJoin(player)), "textures/items/bow_standby"],
    [`§a§lCAMPAL\n§r§8${campalPlayers().length} dentro · entra ya`, () => campalEnter(player), "textures/items/iron_sword"],
    s.pk
      ? ["§2§lSALIR DEL PARKOUR\n§r§8vuelves al lobby", () => {
        stopParkour(player);
        sendToLobby(player);
      }, "textures/items/feather"]
      : [`§2§lPARKOUR\n§r§8${best ? `tu récord: ${fmtMs(best)}` : "sube al Árbol del Mundo"}`, () => {
        tp(player, { x: PK.startPad.x - 1.5, y: LOBBY.y + 1, z: PK.startPad.z - 1.5 }, PK.start);
        player.sendMessage("§2[Parkour]§r Pisa la plataforma azul para empezar.");
      }, "textures/items/feather"],
    [`§d§lMÚSICA\n§r§8${describePlaylist(prefs(player).normal)} · ${prefs(player).volume}%`, () => openMusic(player), "textures/items/record_cat"],
    ["§e§lESTADÍSTICAS\n§r§8las tuyas y el ranking", () => openStats(player), "textures/items/book_normal"],
  ];
  if (isAdmin(player)) buttons.push(["§4§lADMINISTRACIÓN\n§r§8panel de administrador", () => openAdmin(player), "textures/items/clock_item"]);
  await menu(player, "§l§2NATURA PvP", `§fHola, §e${player.name}§f. ¿A qué quieres jugar?\n${queueText}\n `, buttons);
}

async function openStats(player, name = player.name) {
  const s = STATS[name] ?? {};
  const lines = Object.entries(STAT_NAMES).map(([k, label]) => `§7${label}: §f${s[k] ?? 0}`);
  const kd = (s.k ?? 0) / Math.max(1, s.d ?? 0);
  const rank = ["k", "dw", "hw", "ck"].map((k) => `§6${STAT_NAMES[k]}\n${topLines(k)}`).join("\n");
  const pk = topParkour(3).map(([n, v], i) => `§6${i + 1}. §f${n} §7(${fmtMs(v.pk)})`).join("\n") || "§7nadie todavía";
  await menu(player, `§l${name}`, `${lines.join("\n")}\n§7K/D: §f${kd.toFixed(2)}\n§7Récord de parkour: §f${s.pk ? fmtMs(s.pk) : "—"}\n\n§l§eRANKING§r\n${rank}\n§6Parkour\n${pk}\n `, [["§8Cerrar", () => {}]]);
}

