function status() {
  const duels = duel.matches.map((m, i) => (m && m.phase !== "end" ? `§7  ${DUELS[i].name}: §f${m.names[0]} vs ${m.names[1]}` : null)).filter(Boolean);
  const huntText = hunt.phase === "running" ? `§cen curso en ${huntMap().name} §7(cazado: ${hunt.names[hunt.hunted]}, vivos ${hunt.alive.size}, ${fmtTime(hunt.timeLeft)})`
    : `§f${hunt.phase === "countdown" ? `empieza en ${hunt.countdown}s` : "esperando"} §7(cola ${hunt.queue.length}/${S.hunt.maxPlayers})`;
  const builds = AREAS.filter((a) => !built(a.id)).map((a) => a.name);
  return [
    `§fJugadores: §e${world.getPlayers().length}`,
    `§bEmparejamiento: §f${S.duel.enabled ? "activo" : "§cdesactivado"} §7(cola ${duel.queue.length})`,
    ...duels,
    `§cCaza: ${S.hunt.enabled ? huntText : "§cdesactivada"}`,
    `§aCampal: §f${S.campal.enabled ? "abierto" : "§ccerrado"} §7(${campalPlayers().length} dentro)`,
    builds.length ? `§eConstruyendo: ${builds.length} zona(s)${progress.busy ? ` (${progress.label} ${pct()}%)` : ""}` : "",
    " ",
  ].filter((x) => x !== "").join("\n");
}

async function adminMatches(player) {
  const back = () => openAdmin(player);
  await menu(player, "§l§ePARTIDAS EN CURSO", status(), [
    ["§a§lEMPEZAR LA CAZA YA\n§r§8con los que hay en la cola", () => {
      if (hunt.phase === "running" || hunt.phase === "ending") return player.sendMessage("§c[Admin] Ya hay una caza en curso.");
      if (hunt.queue.length < 2) return player.sendMessage("§c[Admin] Hacen falta al menos 2 jugadores en la cola de la caza.");
      startHunt();
    }, "textures/ui/confirm"],
    ["§4§lFORZAR ÚLTIMO EN PIE\n§r§8los cazadores tienen " + S.hunt.lastStandMinutes + " min", async () => {
      if (hunt.phase !== "running") return player.sendMessage("§c[Admin] No hay ninguna caza en curso.");
      if (await confirm(player, "Forzar último en pie", `Los cazadores tendrán solo ${S.hunt.lastStandMinutes} minuto(s) para atrapar al cazado. Si no lo consiguen, gana el cazado.`)) forceLastStand(player);
    }, "textures/items/clock_item"],
    ["§c§lDETENER LA CAZA\n§r§8gana el cazado", async () => {
      if (hunt.phase !== "running") return player.sendMessage("§c[Admin] No hay ninguna caza en curso.");
      if (await confirm(player, "Detener la caza", "La caza termina ahora y gana el cazado.")) endHunt("hunted", "un administrador detuvo la caza");
    }, "textures/ui/cancel"],
    ["§6§lELEGIR EL PRÓXIMO CAZADO", () => chooseHunted(player), "textures/items/name_tag"],
    ["§b§lTERMINAR TODOS LOS DUELOS\n§r§8en empate", () => {
      for (const m of duel.matches) if (m && m.phase !== "end") endDuel(m, undefined, "un administrador terminó el duelo");
    }, "textures/items/diamond_sword"],
    ["§7§lVACIAR LAS COLAS", () => {
      for (const id of [...duel.queue, ...hunt.queue]) byId(id)?.sendMessage("§7Un administrador vació las colas.");
      duel.queue = [];
      hunt.queue = [];
    }, "textures/ui/trash"],
    ["§d§lPARAR LA MÚSICA DE LA CAZA", () => huntMusicStop(), "textures/blocks/barrier"],
  ], back);
}

